<template>
  <view class="app" :class="state.settings.theme" :style="{ '--reading-size': state.settings.fontSize + 'px' }">
    <view class="sidebar">
      <view class="brand" @click="navigate('library')"><text class="brand-icon">拾</text><view><text class="brand-name">拾词</text><text class="brand-sub">WORDBOOK</text></view></view>
      <view class="nav"><button :class="{ active: page === 'library' || page === 'study' || page === 'hidden' }" @click="navigate('library')">▤　我的单词本 <text class="nav-count">{{ state.books.length }}</text></button><button :class="{ active: page === 'import' }" @click="navigate('import')">＋　导入单词本</button><button :class="{ active: page === 'settings' }" @click="navigate('settings')">⚙　基础设置</button></view>
      <view class="sidebar-bottom"><view class="local-dot">●　数据仅保存在此设备</view><text>一点积累，一点进步。</text><text class="version">拾词 · v0.1.0</text></view>
    </view>
    <view class="main">
      <view class="topbar"><text>{{ pageTitle }}</text><view class="top-actions"><text class="offline">● 本地存储</text><button class="icon-btn" aria-label="切换主题" @click="toggleTheme">{{ state.settings.theme === 'dark' ? '☀' : '☾' }}</button></view></view>
      <view v-if="fatal" class="notice error">{{ fatal }}<button @click="exportRaw">导出原始数据</button></view>
      <view v-if="page === 'library'" class="content">
        <view class="page-heading"><view><text class="eyebrow">YOUR PERSONAL VOCABULARY</text><text class="title">把遇见的单词，变成自己的。</text><text class="subtitle">从一本单词本开始，按自己的节奏积累。</text></view><button class="primary" @click="navigate('import')">＋ 导入单词本</button></view>
        <view class="stats"><view><text class="stat-label">我的单词本</text><text class="stat-value">{{ state.books.length }}<text> 本</text></text></view><view><text class="stat-label">全部词汇</text><text class="stat-value">{{ total }}<text> 词</text></text></view><view><text class="stat-label">待记生词</text><text class="stat-value purple">{{ fresh }}<text> 词</text></text></view><view><text class="stat-label">已隐藏</text><text class="stat-value">{{ total - fresh }}<text> 词</text></text></view></view>
        <view class="section-heading"><view><text class="section-title">我的单词本</text><text class="muted">{{ state.books.length }} 本</text></view><input class="search" v-model="search" placeholder="搜索单词本…" aria-label="搜索单词本" /></view>
        <view v-if="!state.books.length" class="empty"><view class="empty-icon">Aa</view><text class="section-title">你的词汇收藏，从这里开始</text><text class="muted">导入 Excel 或 PDF，每个文件成为一本独立的单词本。</text><button class="primary" @click="navigate('import')">导入第一本单词本</button><button class="text-btn" @click="addDemo">先用示例体验</button></view>
        <view v-else-if="!filteredBooks.length" class="empty"><text>没有找到匹配的单词本</text></view>
        <view v-else class="book-grid"><view v-for="(book, i) in filteredBooks" :key="book.id" class="book"><view class="book-top"><view class="book-symbol" :class="'color-' + i % 3">Aa</view><button class="icon-btn" :aria-label="'管理' + book.name" @click="manage(book)">•••</button></view><text class="book-name">{{ book.name }}</text><text class="book-source">{{ book.sourceKey.startsWith('copy:') ? '独立副本' : book.sourceKey.startsWith('demo:') ? '示例单词本' : '文件导入' }} · {{ formatDate(book.updatedAt) }}</text><view class="book-count"><text>{{ book.entries.length }} <text class="muted">总词数</text></text><text class="purple">{{ countNew(book) }} <text class="muted">生词</text></text></view><view class="progress"><view :style="{ width: (book.entries.length ? (book.entries.length - countNew(book)) / book.entries.length * 100 : 0) + '%' }" /></view><view class="book-footer"><button class="text-btn muted" @click="openHidden(book)">隐藏词 {{ book.entries.length - countNew(book) }}</button><button class="start-btn" @click="startStudy(book)">开始背诵 →</button></view></view></view>
        <view class="tip"><text>✧</text><text>记住了，就藏起来。把每一次复习留给还不熟悉的单词。</text></view>
      </view>
      <view v-else-if="page === 'import'" class="content">
        <view class="page-heading"><view><text class="eyebrow">BUILD YOUR COLLECTION</text><text class="title">导入单词本</text><text class="subtitle">先检查，再收藏。每个源文件对应一本单词本。</text></view></view>
        <view class="import-panel"><view class="empty-icon">↥</view><text class="section-title">让你的词汇资料，成为单词卡片</text><text class="muted">Excel / CSV / 文本 PDF / 单词本 JSON · 最大 30 MB</text>
          <!-- #ifndef APP-PLUS -->
          <button class="primary" :disabled="busy" @click="choose">{{ busy ? '正在解析…' : '选择文件' }}</button>
          <!-- #endif -->
          <!-- #ifdef APP-PLUS -->
          <app-file-picker :busy="busy" @busy="busy = $event" @document="onAppDocument" @error="toast" />
          <!-- #endif -->
          <view class="import-options"><button class="text-btn" @click="showPaste = true">粘贴 JSON 恢复</button><button v-if="isDesktop" class="text-btn" @click="scanInput">扫描 dist/input</button></view></view>
        <view v-if="inputFiles.length" class="panel"><text class="section-title">输入目录文件</text><view v-for="file in inputFiles" :key="file" class="file-row"><text>{{ file }}</text><button class="secondary" :disabled="busy" @click="readInput(file)">解析并预览</button></view></view>
        <view class="panel instructions"><text class="section-title">导入说明</text><text>01　Excel 推荐表头：单词 / 音标 / 释义 / 例句；自动读取所有工作表。</text><text>02　无表头时按上述四列读取；PDF 推荐每行一个词，列间保留空白。</text><text>03　同名文件覆盖原单词本内容，保留仍存在词条的隐藏状态；被剔除的词条会从原本移除。</text><text>04　扫描图片型 PDF 请先 OCR。手机不能扫描电脑目录，可导入电脑导出的 JSON。</text><text>05　微信端支持从聊天文件选择 Excel / JSON；PDF 请先用电脑生成预览 JSON。</text></view>
      </view>
      <view v-else-if="page === 'study' && currentBook" class="content study-content">
        <view class="study-heading"><button class="text-btn" @click="navigate('library')">← 我的单词本</button><button class="text-btn" @click="openHidden(currentBook)">隐藏词 {{ currentBook.entries.length - countNew(currentBook) }}</button></view>
        <view class="study-title"><text class="title">{{ currentBook.name }}</text><text class="muted">只与还不熟悉的单词相遇</text></view>
        <view class="study-controls"><view class="segmented"><button :class="{ selected: order === 'alpha' }" @click="changeOrder('alpha')">A–Z 字母顺序</button><button :class="{ selected: order === 'random' }" @click="changeOrder('random')">⇄ 完全乱序</button></view><text class="muted">{{ queue.length ? cursor + 1 : 0 }} / {{ queue.length }}</text></view>
        <view v-if="currentEntry" class="flashcard" :class="{ flipped }" @click="flipped = !flipped" role="button" :aria-label="flipped ? '翻到单词正面' : '翻看释义'"><view class="card-top"><text>{{ flipped ? '释义 · DEFINITION' : '单词 · WORD' }}</text><button class="sound" aria-label="播放发音" @click.stop="pronounce(currentEntry.word)">♫</button></view><view class="card-body"><text class="card-word">{{ currentEntry.word }}</text><template v-if="flipped"><text class="phonetic">{{ currentEntry.phonetic || '暂无音标' }}</text><text class="meaning">{{ currentEntry.meaning || '暂无释义' }}</text><text class="example">{{ currentEntry.example || '暂无例句' }}</text></template><text v-else class="flip-hint">轻触卡片，查看释义与例句</text></view><text class="card-bottom">↻ {{ flipped ? '点击返回单词' : '点击翻转卡片' }}</text></view>
        <view v-else class="empty panel"><text class="empty-icon">✓</text><text class="section-title">这本单词本没有待记生词了</text><button class="primary" @click="openHidden(currentBook)">查看隐藏词，恢复复习</button></view>
        <view v-if="currentEntry" class="study-buttons"><button class="secondary" @click="step(-1)">← 上一个</button><button class="hide-btn" @click="hideCurrent">✓ 已记住，隐藏</button><button class="primary" @click="step(1)">下一个 →</button></view><text v-if="currentEntry" class="study-note">隐藏的单词将退出背诵轮询，随时可在隐藏词列表恢复。</text>
      </view>
      <view v-else-if="page === 'hidden' && currentBook" class="content"><button class="text-btn" @click="startStudy(currentBook)">← 返回背诵</button><view class="page-heading"><view><text class="title">隐藏词</text><text class="subtitle">{{ currentBook.name }} · {{ hiddenEntries.length }} 词，恢复后将重新参与背诵。</text></view><button v-if="hiddenEntries.length" class="secondary" @click="restoreAll">全部恢复</button></view><view v-if="!hiddenEntries.length" class="empty panel"><text>还没有隐藏的单词</text></view><view v-else class="panel"><view v-for="entry in hiddenEntries" :key="entry.id" class="hidden-row"><view><text class="hidden-word">{{ entry.word }}</text><text class="muted">{{ entry.meaning }}</text></view><button class="secondary" @click="restore(entry.id)">恢复为生词</button></view></view></view>
      <view v-else-if="page === 'settings'" class="content settings"><view class="page-heading"><view><text class="eyebrow">MAKE IT YOURS</text><text class="title">基础设置</text><text class="subtitle">舒服的阅读节奏，让记忆更轻松。</text></view></view><view class="panel"><view class="setting-row"><view><text class="section-title">外观主题</text><text class="muted">随时在浅色和深色之间切换</text></view><view class="segmented"><button :class="{ selected: state.settings.theme === 'light' }" @click="setTheme('light')">☀ 浅色</button><button :class="{ selected: state.settings.theme === 'dark' }" @click="setTheme('dark')">☾ 深色</button></view></view><view class="setting-row"><view><text class="section-title">卡片字体大小</text><text class="muted">{{ state.settings.fontSize }} px</text></view><slider :value="state.settings.fontSize" :min="14" :max="28" :step="1" activeColor="#7563d9" @change="setFont($event.detail.value)" /></view><view class="font-preview" :style="{ fontSize: state.settings.fontSize + 'px' }">Every word is a new beginning.<text>每一个单词，都是新的开始。</text></view></view><view class="panel"><text class="section-title">数据与备份</text><text class="subtitle">数据保存在当前设备。清除浏览器或应用数据会丢失单词本，请定期导出。</text><view class="import-options"><button class="primary" @click="exportAll">导出全部数据</button><button class="secondary" @click="navigate('import')">导入备份恢复</button></view></view></view>
    </view>
    <view v-if="preview" class="overlay"><view class="modal wide"><view class="modal-heading"><view><text class="section-title">检查导入内容</text><text class="muted">{{ preview.entries.length }} 条解析结果 · 选中 {{ selectedCount }} 条</text></view><button class="icon-btn" aria-label="关闭预览" @click="preview = null">×</button></view><input v-model="preview.name" :disabled="!!replacing" class="name-input" placeholder="单词本名称" aria-label="单词本名称" /><text v-if="replacing" class="notice">将覆盖「{{ replacing.name }}」：未选中的词条会移除；已有隐藏状态保留。</text><view class="preview-actions"><button class="text-btn" @click="selectPreview(true)">全选</button><button class="text-btn" @click="selectPreview(false)">全不选</button><text class="muted">警告行默认不选；可编辑修正后勾选。</text></view><scroll-view scroll-y class="preview-list"><view v-for="row in previewRows" :key="row.reviewId" class="preview-row" :class="{ excluded: !row.selected }"><button class="check" :class="{ checked: row.selected }" :aria-label="(row.selected ? '剔除 ' : '保留 ') + row.word" @click="row.selected = !row.selected">{{ row.selected ? '✓' : '−' }}</button><view class="preview-fields"><input v-model="row.word" :maxlength="-1" placeholder="单词" aria-label="词条单词" /><input v-model="row.phonetic" :maxlength="-1" placeholder="音标" aria-label="词条音标" /><input v-model="row.meaning" :maxlength="-1" placeholder="释义" aria-label="词条释义" /><input v-model="row.example" :maxlength="-1" placeholder="例句" aria-label="词条例句" /><text class="row-warning">{{ row.location }} {{ row.warning }}</text></view></view></scroll-view><view class="preview-pagination"><button class="text-btn" :disabled="previewPage <= 1" @click="previewPage--">← 上一页</button><text class="muted">{{ previewPage }} / {{ previewPages }} 页 · 每页 50 条</text><button class="text-btn" :disabled="previewPage >= previewPages" @click="previewPage++">下一页 →</button></view><view class="modal-footer"><button class="secondary" @click="preview = null">取消</button><button class="primary" :disabled="!selectedCount || !!fatal" @click="commitImport">{{ replacing ? '确认覆盖更新' : '创建单词本' }}</button></view></view></view>
    <view v-if="showPaste" class="overlay"><view class="modal"><text class="section-title">粘贴单词本 JSON</text><text class="subtitle">支持备份文件或电脑扫描生成的预览文件内容。</text><textarea class="paste-area" v-model="pasteText" placeholder="粘贴 JSON 内容" :maxlength="-1" /><view class="modal-footer"><button class="secondary" @click="showPaste = false">取消</button><button class="primary" @click="parsePasted">检查内容</button></view></view></view>
    <view v-if="restoreDraft" class="overlay"><view class="modal"><text class="section-title">恢复备份</text><text class="subtitle">文件包含 {{ restoreDraft.books.length }} 本单词本、{{ restoreDraft.books.reduce((n,b) => n + b.entries.length, 0) }} 个词条。相同单词本将被备份中的内容覆盖；其他单词本保留。</text><view class="modal-footer"><button class="secondary" @click="restoreDraft = null">取消</button><button class="primary" @click="commitRestore">确认合并恢复</button></view></view></view>
    <view v-if="renameDraft" class="overlay"><view class="modal"><text class="section-title">重命名单词本</text><input class="name-input" v-model="renameDraft.name" :maxlength="100" /><view class="modal-footer"><button class="secondary" @click="renameDraft = null">取消</button><button class="primary" @click="commitRename">保存名称</button></view></view></view>
    <view v-if="busy" class="busy-indicator">正在解析文件，请稍候…</view>
  </view>
</template>

<script setup>
import { ref, computed, nextTick } from 'vue';
import { emptyState, importBook, copyBook, makeQueue, validateBackup, mergeBackup, keyOf } from '../../core/model.mjs';
import { reviewEntries } from '../../core/parse.mjs';
import { loadState, saveState, rawState } from '../../platform/storage.js';
import { pickFile, exportFile, desktop, readDocument } from '../../platform/files.js';
import { speak } from '../../platform/speech.js';
// #ifdef APP-PLUS
import AppFilePicker from '../../components/app-file-picker.vue';
// #endif
const state = ref(emptyState()), fatal = ref('');
try { state.value = loadState(); } catch (e) { fatal.value = e.message; }
const page = ref('library'), search = ref(''), busy = ref(false), preview = ref(null), inputFiles = ref([]), isDesktop = !!desktop();
const activeId = ref(''), queue = ref([]), cursor = ref(0), flipped = ref(false), order = ref('alpha');
const showPaste = ref(false), pasteText = ref(''), restoreDraft = ref(null), renameDraft = ref(null);
const previewPage = ref(1);
const previewPages = computed(() => Math.max(1, Math.ceil((preview.value?.entries.length || 0) / 50)));
const previewRows = computed(() => preview.value?.entries.slice((previewPage.value - 1) * 50, previewPage.value * 50) || []);
const pageTitle = computed(() => ({ library: '我的单词本', import: '导入单词本', settings: '基础设置', study: '单词卡片', hidden: '隐藏词列表' }[page.value]));
const total = computed(() => state.value.books.reduce((n, b) => n + b.entries.length, 0));
const fresh = computed(() => state.value.books.reduce((n, b) => n + countNew(b), 0));
const filteredBooks = computed(() => state.value.books.filter(b => b.name.toLowerCase().includes(search.value.toLowerCase())));
const currentBook = computed(() => state.value.books.find(b => b.id === activeId.value));
const currentEntry = computed(() => currentBook.value?.entries.find(e => e.id === queue.value[cursor.value]));
const hiddenEntries = computed(() => currentBook.value?.entries.filter(e => e.status === 'hidden') || []);
const selectedCount = computed(() => preview.value?.entries.filter(e => e.selected).length || 0);
const replacing = computed(() => state.value.books.find(b => b.sourceKey === preview.value?.sourceKey));
const countNew = b => b.entries.filter(e => e.status === 'new').length;
const formatDate = value => value?.slice(0, 10).replaceAll('-', '.') || '';
const toast = title => uni.showToast({ title, icon: 'none', duration: 3000 });
function commit(next) {
  if (fatal.value) { toast(fatal.value); return false; }
  try { saveState(next); state.value = next; return true; } catch { toast('保存失败，可能存储空间不足。请先导出备份。'); return false; }
}
function navigate(target) { page.value = target; nextTick(() => uni.pageScrollTo({ scrollTop: 0, duration: 0 })); }
function updateBook(fn) { return commit({ ...state.value, books: state.value.books.map(b => b.id === activeId.value ? fn({ ...b, entries: b.entries.map(e => ({ ...e })) }) : b) }); }
function setTheme(theme) { commit({ ...state.value, settings: { ...state.value.settings, theme } }); }
function toggleTheme() { setTheme(state.value.settings.theme === 'dark' ? 'light' : 'dark'); }
function setFont(fontSize) { commit({ ...state.value, settings: { ...state.value.settings, fontSize } }); }
function rebuild() { queue.value = makeQueue(currentBook.value, order.value).map(e => e.id); cursor.value = 0; flipped.value = false; }
function startStudy(book) { activeId.value = book.id; rebuild(); navigate('study'); }
function openHidden(book) { activeId.value = book.id; navigate('hidden'); }
function changeOrder(value) { order.value = value; rebuild(); }
function step(delta) { cursor.value = (cursor.value + delta + queue.value.length) % queue.value.length; flipped.value = false; }
function hideCurrent() {
  const id = currentEntry.value.id;
  if (updateBook(b => { b.entries.find(e => e.id === id).status = 'hidden'; return b; })) {
    queue.value.splice(cursor.value, 1); if (cursor.value >= queue.value.length) cursor.value = 0; flipped.value = false;
  }
}
function restore(id) { updateBook(b => { b.entries.find(e => e.id === id).status = 'new'; return b; }); }
function restoreAll() { updateBook(b => { b.entries.forEach(e => e.status = 'new'); return b; }); }
function pronounce(word) { try { speak(word); } catch (e) { toast(e.message); } }
async function choose() { try { busy.value = true; const value = await pickFile(); if (value) acceptDocument(value); } catch (e) { toast(e.message); } finally { busy.value = false; } }
function acceptDocument(value) {
  previewPage.value = 1;
  if (value?.format === 'wordbook-preview' || (value?.sourceKey && value?.entries)) {
    if (typeof value.name !== 'string' || typeof value.sourceKey !== 'string' || !Array.isArray(value.entries) || value.entries.some(e => !e || typeof e.word !== 'string')) throw Error('预览文件格式无效');
    preview.value = { ...value, entries: reviewEntries(value.entries.map(e => ({ word: e.word, meaning: String(e.meaning || ''), phonetic: String(e.phonetic || ''), example: String(e.example || ''), location: e.location || '' }))) };
  } else restoreDraft.value = validateBackup(value);
}
function onAppDocument(value) { try { acceptDocument(value); } catch (e) { toast(e.message); } }
function selectPreview(selected) { preview.value.entries.forEach(row => row.selected = selected); }
function commitImport() {
  try {
    const entries = preview.value.entries.filter(e => e.selected);
    const seen = new Set();
    for (const e of entries) { if (!e.word.trim()) throw Error('选中词条的单词不能为空'); if (seen.has(keyOf(e.word))) throw Error('选中词条仍有重复，请先剔除或修改'); seen.add(keyOf(e.word)); }
    if (commit(importBook(state.value, preview.value.name, preview.value.sourceKey, entries))) { preview.value = null; navigate('library'); toast('单词本已保存'); }
  } catch (e) { toast(e.message); }
}
function parsePasted() { try { acceptDocument(JSON.parse(pasteText.value)); showPaste.value = false; pasteText.value = ''; } catch (e) { toast(e.message); } }
function commitRestore() {
  try {
    const next = mergeBackup(state.value, restoreDraft.value);
    if (fatal.value) { saveState(next); state.value = next; fatal.value = ''; }
    else if (!commit(next)) return;
    restoreDraft.value = null; navigate('library'); toast('备份已恢复');
  } catch (e) { toast(e.message); }
}
async function scanInput() { try { inputFiles.value = await desktop().listInput(); if (!inputFiles.value.length) toast('dist/input 中没有 Excel、CSV 或 PDF 文件'); } catch (e) { toast(e.message); } }
async function readInput(name) { try { busy.value = true; acceptDocument(await readDocument(name, new Uint8Array(await desktop().readInput(name)))); } catch (e) { toast(e.message); } finally { busy.value = false; } }
async function exportAll() { try { await exportFile('wordbook-backup.json', state.value); } catch (e) { toast(e.message); } }
async function exportRaw() { try { await exportFile('wordbook-raw-backup.json', rawState()); } catch (e) { toast(e.message); } }
function manage(book) {
  uni.showActionSheet({ itemList: ['重命名', '复制单词本', '导出单词本', '查看隐藏词', '删除单词本'], success: async ({ tapIndex }) => {
    if (tapIndex === 0) renameDraft.value = { id: book.id, name: book.name };
    if (tapIndex === 1 && commit(copyBook(state.value, book.id))) toast('已创建独立副本');
    if (tapIndex === 2) { try { await exportFile(`${book.name.replace(/[<>:"/\\|?*\x00-\x1f]/g, '_')}.wordbook.json`, { ...state.value, books: [book] }); } catch (e) { toast(e.message); } }
    if (tapIndex === 3) openHidden(book);
    if (tapIndex === 4) uni.showModal({ title: '删除单词本', content: `确定删除「${book.name}」及其全部词条？建议先导出备份。`, success: ({ confirm }) => { if (confirm) commit({ ...state.value, books: state.value.books.filter(b => b.id !== book.id) }); } });
  } });
}
function commitRename() { if (!renameDraft.value.name.trim()) return toast('名称不能为空'); if (commit({ ...state.value, books: state.value.books.map(b => b.id === renameDraft.value.id ? { ...b, name: renameDraft.value.name.trim() } : b) })) renameDraft.value = null; }
function addDemo() {
  const entries = [
    ['serendipity', '/ˌserənˈdɪpəti/', 'n. 意外发现美好事物的运气；机缘巧合', 'Finding this little bookshop was pure serendipity.'],
    ['bloom', '/bluːm/', 'v. 开花；蓬勃发展', 'The cherry trees bloom in spring.'],
    ['curiosity', '/ˌkjʊriˈɑːsəti/', 'n. 好奇心；求知欲', 'Curiosity opens the door to learning.'],
    ['wander', '/ˈwɑːndər/', 'v. 漫步；徘徊', 'We wandered through the quiet streets.'],
    ['resilient', '/rɪˈzɪliənt/', 'adj. 有韧性的；能恢复的', 'Small steps help us become more resilient.'],
    ['embrace', '/ɪmˈbreɪs/', 'v. 拥抱；欣然接受', 'Embrace every opportunity to learn.']
  ].map(([word, phonetic, meaning, example]) => ({ word, phonetic, meaning, example }));
